"""The tallybook web API: JSON over HTTP on top of the book file (http.server only)."""
import json
import re
import signal
import socket
import sys
import threading
from datetime import date
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote_to_bytes

from tallybook import __version__
from tallybook import budgets as budgets_mod
from tallybook import recurring as recurring_mod
from tallybook import reports as reports_mod
from tallybook.dates import Period, format_date, parse_date
from tallybook.errors import ConflictError, NotFoundError, ParseError, TallybookError, ValidationError
from tallybook.export import (
    money_to_dict,
    to_json,
    transaction_to_dict,
    transactions_to_csv,
)
from tallybook.journal import format_journal
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.storage import Store

MAX_BODY = 1048576
MAX_WHOLE = 9223372036854775807
REQUEST_TIMEOUT = 10.0
MAX_DRAIN = 256 * 1024 * 1024

JSON_TYPE = "application/json; charset=utf-8"
TEXT_TYPE = "text/plain; charset=utf-8"
CSV_TYPE = "text/csv; charset=utf-8"

_DIGITS = re.compile(r"[0-9]+")
_STATUS = {"parse": 400, "validation": 400, "not_found": 404, "conflict": 409}


class HttpError(Exception):
    def __init__(self, status, message, allow=None):
        super().__init__(message)
        self.status = status
        self.message = message
        self.allow = allow


# -- request helpers ---------------------------------------------------------


def _decode(raw):
    try:
        return unquote_to_bytes(raw).decode("utf-8")
    except UnicodeDecodeError:
        return None


def split_target(target):
    """Return (pieces or None, raw query text) of a request target."""
    target = target.split("#", 1)[0]
    path, _, query = target.partition("?")
    if not path.startswith("/"):
        return None, query
    pieces = []
    for raw in path[1:].split("/"):
        piece = _decode(raw.encode("latin-1", "replace"))
        if piece is None:
            return None, query
        pieces.append(piece)
    return pieces, query


def parse_query(raw):
    out = {}
    for part in raw.split("&"):
        if not part:
            continue
        name, _, value = part.partition("=")
        decoded = []
        for item in (name, value):
            text = _decode(item.replace("+", " ").encode("latin-1", "replace"))
            if text is None:
                raise ParseError("query string is not valid UTF-8")
            decoded.append(text)
        out[decoded[0]] = decoded[1]
    return out


def _has_surrogate(value):
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, str):
            try:
                item.encode("utf-8")
            except UnicodeEncodeError:
                return True
        elif isinstance(item, list):
            stack.extend(item)
        elif isinstance(item, dict):
            stack.extend(item.keys())
            stack.extend(item.values())
    return False


def _no_constant(name):
    raise ValueError("invalid constant %s" % name)


def load_json_object(body):
    if not body:
        return {}
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError:
        raise ParseError("request body is not valid UTF-8") from None
    try:
        data = json.loads(text, parse_constant=_no_constant)
    except (ValueError, RecursionError) as exc:
        raise ParseError("request body is not valid JSON: %s" % exc) from None
    if _has_surrogate(data):
        raise ParseError("request body is not valid UTF-8")
    if not isinstance(data, dict):
        raise ValidationError("request body must be a JSON object")
    return data


def _money(value, name):
    if isinstance(value, str):
        return Money.parse(value)
    if (
        isinstance(value, dict)
        and set(value) == {"amount", "currency"}
        and isinstance(value["amount"], str)
        and isinstance(value["currency"], str)
    ):
        return Money.of(value["amount"], value["currency"])
    raise ValidationError(
        'field %s must be text like "12.50 USD" or an object with text fields amount and currency' % name
    )


def _convert(kind, value, name):
    if kind == "text":
        if not isinstance(value, str):
            raise ValidationError("field %s must be text" % name)
        return value
    if kind == "int":
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValidationError("field %s must be a whole number" % name)
        return value
    if kind == "bool":
        if not isinstance(value, bool):
            raise ValidationError("field %s must be true or false" % name)
        return value
    if kind == "date":
        if not isinstance(value, str):
            raise ValidationError("field %s must be a date as text YYYY-MM-DD" % name)
        return parse_date(value)
    if kind == "money":
        return _money(value, name)
    if kind == "list":
        if not isinstance(value, list):
            raise ValidationError("field %s must be a list" % name)
        return value
    if kind == "textlist":
        if not isinstance(value, list) or not all(isinstance(v, str) for v in value):
            raise ValidationError("field %s must be a list of text" % name)
        return value
    if kind == "object":
        if not isinstance(value, dict):
            raise ValidationError("field %s must be an object" % name)
        return value
    raise AssertionError(kind)


def take(obj, spec, where=""):
    """Check an object against spec {name: (kind, required)}; absent and null are the same."""
    for key in obj:
        if key not in spec:
            raise ValidationError("unknown field: %s%s" % (key, where))
    out = {}
    for name, (kind, required) in spec.items():
        value = obj.get(name)
        if value is None:
            if required:
                raise ValidationError("missing field: %s%s" % (name, where))
            out[name] = None
        else:
            out[name] = _convert(kind, value, name)
    return out


_POSTING = {"account": ("text", True), "amount": ("money", False), "note": ("text", False)}


def build_postings(items):
    postings = []
    for index, item in enumerate(items, 1):
        where = " (in posting %d)" % index
        if not isinstance(item, dict):
            raise ValidationError("posting %d must be an object" % index)
        f = take(item, _POSTING, where)
        postings.append(Posting(f["account"], f["amount"], f["note"] or ""))
    return postings


_TX = {
    "date": ("date", True),
    "payee": ("text", True),
    "narration": ("text", False),
    "flag": ("text", False),
    "tags": ("textlist", False),
    "postings": ("list", True),
}


def build_transaction(obj):
    f = take(obj, _TX)
    return Transaction(
        f["date"],
        f["payee"],
        f["narration"] or "",
        build_postings(f["postings"]),
        tuple(f["tags"] or ()),
        "*" if f["flag"] is None else f["flag"],
        None,
    )


_TEMPLATE = {
    "payee": ("text", True),
    "narration": ("text", False),
    "flag": ("text", False),
    "tags": ("textlist", False),
    "postings": ("list", True),
}


def build_template(obj, when):
    f = take(obj, _TEMPLATE, " (in template)")
    return Transaction(
        when,
        f["payee"],
        f["narration"] or "",
        build_postings(f["postings"]),
        tuple(f["tags"] or ()),
        "*" if f["flag"] is None else f["flag"],
        None,
    )


# -- shapes ------------------------------------------------------------------


def _day(d):
    return None if d is None else format_date(d)


def account_dict(a):
    return {
        "path": a.path,
        "type": a.type,
        "currency": a.currency,
        "opened": _day(a.opened),
        "closed": _day(a.closed),
        "note": a.note,
    }


def rate_dict(src, dst, on, text):
    return {"src": src, "dst": dst, "date": _day(on), "rate": text}


def budget_dict(b):
    return {
        "pattern": b.pattern,
        "period_kind": b.period_kind,
        "amount": money_to_dict(b.amount),
        "start": _day(b.start),
    }


def recurring_dict(rec):
    t = rec.template
    return {
        "name": rec.name,
        "schedule": str(rec.schedule),
        "start": _day(rec.start),
        "end": _day(rec.end),
        "count": rec.count,
        "template": {
            "payee": t.payee,
            "narration": t.narration,
            "flag": t.flag,
            "tags": sorted(set(t.tags)),
            "postings": [
                {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note} for p in t.postings
            ],
        },
    }


# -- one request -------------------------------------------------------------


class Request:
    def __init__(self, server, method, pieces, raw_query, body):
        self.server = server
        self.method = method
        self.pieces = pieces
        self.raw_query = raw_query
        self.body = body
        self.content_type = ""
        self._query = None
        self._json = None

    @property
    def today(self):
        return self.server.today if self.server.today is not None else date.today()

    def open_store(self):
        return Store.open(self.server.db_path)

    @property
    def query(self):
        if self._query is None:
            self._query = parse_query(self.raw_query)
        return self._query

    def param(self, name):
        return self.query.get(name)

    def need(self, name):
        value = self.query.get(name)
        if value is None:
            raise ValidationError("missing query parameter: %s" % name)
        return value

    def yesno(self, name, default):
        value = self.query.get(name)
        if value is None:
            return default
        low = value.lower()
        if low in ("true", "yes", "1"):
            return True
        if low in ("false", "no", "0"):
            return False
        raise ValidationError("invalid %s %r: expected true, false, yes, no, 1 or 0" % (name, value))

    def whole(self, name, default):
        value = self.query.get(name)
        if value is None:
            return default
        if _DIGITS.fullmatch(value) is None or len(value.lstrip("0")) > 19 or int(value) > MAX_WHOLE:
            raise ValidationError("invalid %s %r: expected a whole number from 0 to %d" % (name, value, MAX_WHOLE))
        return int(value)

    def date_param(self, name, required=False):
        value = self.need(name) if required else self.query.get(name)
        return None if value is None else parse_date(value)

    def period_param(self, name="period", required=True):
        value = self.need(name) if required else self.query.get(name)
        return None if value is None else Period.parse(value)

    def obj(self):
        if self._json is None:
            self._json = load_json_object(self.body)
        return self._json


def json_reply(obj, status=200):
    return status, JSON_TYPE, to_json(obj).encode("utf-8")


def text_reply(text, kind=TEXT_TYPE):
    return 200, kind, text.encode("utf-8")


# -- handlers ----------------------------------------------------------------


def h_health(rq):
    with rq.open_store() as store:
        return json_reply({"status": "ok", "version": __version__, "schema_version": store.version})


def h_accounts_list(rq):
    kind = rq.param("type")
    under = rq.param("under")
    cur = rq.param("currency")
    include_closed = rq.yesno("include_closed", True)
    with rq.open_store() as store:
        items = store.accounts(type=kind, under=under, currency=cur, include_closed=include_closed)
    return json_reply([account_dict(a) for a in items])


_ACCOUNT = {
    "path": ("text", True),
    "type": ("text", False),
    "currency": ("text", False),
    "opened": ("date", False),
    "note": ("text", False),
}


def h_accounts_add(rq):
    f = take(rq.obj(), _ACCOUNT)
    with rq.open_store() as store:
        account = store.add_account(f["path"], f["type"], f["currency"], f["opened"], f["note"] or "")
    return json_reply(account_dict(account), 201)


def h_account_get(rq):
    with rq.open_store() as store:
        return json_reply(account_dict(store.get_account(rq.pieces[1])))


def h_account_close(rq):
    f = take(rq.obj(), {"on": ("date", False)})
    on = f["on"] if f["on"] is not None else rq.today
    with rq.open_store() as store:
        return json_reply(account_dict(store.close_account(rq.pieces[1], on)))


def h_tx_list(rq):
    q = rq.param("q") or None
    limit = rq.whole("limit", None)
    offset = rq.whole("offset", 0)
    with rq.open_store() as store:
        items = store.transactions(q, limit, offset)
        total = store.count_transactions(q)
    return json_reply(
        {"items": [transaction_to_dict(t) for t in items], "total": total, "limit": limit, "offset": offset}
    )


def h_tx_add(rq):
    tx = build_transaction(rq.obj())
    with rq.open_store() as store:
        return json_reply(transaction_to_dict(store.add_transaction(tx)), 201)


def _tx_id(rq):
    digits = rq.pieces[1].lstrip("0")
    if len(digits) > 19 or (digits and int(digits) > MAX_WHOLE):
        raise NotFoundError("no such transaction: %s" % rq.pieces[1])
    return int(digits or "0")


def h_tx_get(rq):
    with rq.open_store() as store:
        return json_reply(transaction_to_dict(store.get_transaction(_tx_id(rq))))


def h_tx_delete(rq):
    with rq.open_store() as store:
        return json_reply(transaction_to_dict(store.delete_transaction(_tx_id(rq))))


def h_rates_list(rq):
    with rq.open_store() as store:
        rows = store.rate_rows()
    return json_reply([rate_dict(*r) for r in rows])


_RATE = {"src": ("text", True), "dst": ("text", True), "date": ("date", True), "rate": ("text", True)}


def h_rates_put(rq):
    f = take(rq.obj(), _RATE)
    with rq.open_store() as store:
        store.set_rate(f["src"], f["dst"], f["rate"], f["date"])
    return json_reply(rate_dict(f["src"], f["dst"], f["date"], f["rate"]))


def h_rates_delete(rq):
    src, dst = rq.need("src"), rq.need("dst")
    on = rq.date_param("date", True)
    with rq.open_store() as store:
        text = ""
        for s, d, o, t in store.rate_rows():
            if (s, d, o) == (src, dst, on):
                text = t
        store.remove_rate(src, dst, on)
    return json_reply(rate_dict(src, dst, on, text))


def h_budgets_list(rq):
    with rq.open_store() as store:
        items = store.budgets()
    return json_reply([budget_dict(b) for b in items])


_BUDGET = {
    "pattern": ("text", True),
    "period_kind": ("text", True),
    "amount": ("money", True),
    "start": ("date", True),
}


def h_budgets_add(rq):
    f = take(rq.obj(), _BUDGET)
    budget = budgets_mod.Budget(f["pattern"], f["period_kind"], f["amount"], f["start"])
    with rq.open_store() as store:
        store.add_budget(budget)
    return json_reply(budget_dict(budget), 201)


def h_budgets_delete(rq):
    pattern, kind = rq.need("pattern"), rq.need("period_kind")
    with rq.open_store() as store:
        found = [b for b in store.budgets() if b.pattern == pattern and b.period_kind == kind]
        store.remove_budget(pattern, kind)
    return json_reply(budget_dict(found[0]) if found else {"pattern": pattern, "period_kind": kind})


def h_budgets_status(rq):
    period = rq.period_param()
    with rq.open_store() as store:
        lines = budgets_mod.budget_status(store.budgets(), store.ledger(), period)
    return json_reply([ln.to_dict() for ln in lines])


def h_recurring_list(rq):
    with rq.open_store() as store:
        items = store.recurring()
    return json_reply([recurring_dict(r) for r in items])


_RECURRING = {
    "name": ("text", True),
    "schedule": ("text", True),
    "start": ("date", True),
    "end": ("date", False),
    "count": ("int", False),
    "template": ("object", True),
}


def h_recurring_add(rq):
    f = take(rq.obj(), _RECURRING)
    template = build_template(f["template"], f["start"])
    rec = recurring_mod.Recurring(f["name"], f["schedule"], template, f["start"], f["end"], f["count"])
    with rq.open_store() as store:
        store.add_recurring(rec)
    return json_reply(recurring_dict(rec), 201)


def h_recurring_delete(rq):
    name = rq.need("name")
    with rq.open_store() as store:
        found = [r for r in store.recurring() if r.name == name]
        store.remove_recurring(name)
    return json_reply(recurring_dict(found[0]) if found else {"name": name})


def h_materialize(rq):
    f = take(rq.obj(), {"upto": ("date", False)})
    with rq.open_store() as store:
        made = store.materialize(upto=f["upto"], today=rq.today)
    return json_reply({"added": [transaction_to_dict(t) for t in made]})


def _report_format(rq):
    value = rq.param("format")
    if value is None or value == "json":
        return "json"
    if value == "text":
        return "text"
    raise ValidationError("invalid format %r: expected json or text" % value)


def h_report(rq):
    name = rq.pieces[1]
    fmt = _report_format(rq)
    if name == "trial-balance":
        as_of = rq.date_param("as_of")
        run = lambda ledger: reports_mod.trial_balance(ledger, as_of)
    elif name == "balance-sheet":
        as_of = rq.date_param("as_of")
        convert = rq.param("convert_to")
        run = lambda ledger: reports_mod.balance_sheet(ledger, as_of, convert, today=rq.today)
    elif name == "income-statement":
        period = rq.period_param()
        convert = rq.param("convert_to")
        run = lambda ledger: reports_mod.income_statement(ledger, period, convert)
    elif name == "cashflow":
        period = rq.period_param()
        run = lambda ledger: reports_mod.cashflow(ledger, period)
    else:
        account = rq.need("account")
        period = rq.period_param(required=False)
        rollup = rq.yesno("rollup", False)
        run = lambda ledger: reports_mod.register(ledger, account, period, rollup)
    with rq.open_store() as store:
        report = run(store.ledger())
    if fmt == "text":
        return text_reply(reports_mod.render_text(report))
    return json_reply(report)


def h_import(rq):
    if rq.body and rq.content_type == "application/json":
        f = take(rq.obj(), {"csv": ("text", True), "profile": ("text", True), "apply_rules": ("bool", False)})
        text, profile = f["csv"], f["profile"]
        apply_rules = True if f["apply_rules"] is None else f["apply_rules"]
    else:
        profile = rq.need("profile")
        apply_rules = rq.yesno("apply_rules", True)
        try:
            text = rq.body.decode("utf-8")
        except UnicodeDecodeError:
            raise ParseError("request body is not valid UTF-8") from None
    with rq.open_store() as store:
        outcome = store.import_csv(text, profile, apply_rules=apply_rules)
    if outcome.errors:
        raise ValidationError(
            "import failed: " + "; ".join("row %d: %s" % (n, msg) for n, msg in outcome.errors)
        )
    duplicates = []
    for tx in outcome.duplicates:
        d = transaction_to_dict(tx)
        d["id"] = None
        duplicates.append(d)
    return json_reply({"added": [transaction_to_dict(t) for t in outcome.added], "duplicates": duplicates})


def h_rules_get(rq):
    with rq.open_store() as store:
        return json_reply({"rules": store.rules_text()})


def h_rules_put(rq):
    f = take(rq.obj(), {"rules": ("text", True)})
    with rq.open_store() as store:
        store.set_rules(f["rules"])
        return json_reply({"rules": store.rules_text()})


def h_export(rq):
    value = rq.param("format")
    if value is not None and value not in ("json", "csv", "journal"):
        raise ValidationError("invalid format %r: expected json, csv or journal" % value)
    with rq.open_store() as store:
        if value == "journal":
            return text_reply(format_journal(store.journal()))
        txs = store.transactions()
    if value == "csv":
        return text_reply(transactions_to_csv(txs), CSV_TYPE)
    return json_reply([transaction_to_dict(t) for t in txs])


# -- routing -----------------------------------------------------------------

_JSON = ("application/json",)
_IMPORT = ("text/csv", "text/plain", "application/json")
_REPORTS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


def route(pieces):
    """Return {VERB: (handler, accepted body types)} for a path, or None when the path is unknown."""
    n = len(pieces)
    if any(p == "" for p in pieces):
        return None
    head = pieces[0]
    if n == 1:
        table = {
            "health": {"GET": (h_health, _JSON)},
            "accounts": {"GET": (h_accounts_list, _JSON), "POST": (h_accounts_add, _JSON)},
            "transactions": {"GET": (h_tx_list, _JSON), "POST": (h_tx_add, _JSON)},
            "rates": {"GET": (h_rates_list, _JSON), "PUT": (h_rates_put, _JSON), "DELETE": (h_rates_delete, _JSON)},
            "budgets": {
                "GET": (h_budgets_list, _JSON),
                "POST": (h_budgets_add, _JSON),
                "DELETE": (h_budgets_delete, _JSON),
            },
            "recurring": {
                "GET": (h_recurring_list, _JSON),
                "POST": (h_recurring_add, _JSON),
                "DELETE": (h_recurring_delete, _JSON),
            },
            "rules": {"GET": (h_rules_get, _JSON), "PUT": (h_rules_put, _JSON)},
            "export": {"GET": (h_export, _JSON)},
            "import": {"POST": (h_import, _IMPORT)},
        }
        return table.get(head)
    if n == 2:
        second = pieces[1]
        if head == "accounts":
            return {"GET": (h_account_get, _JSON)}
        if head == "transactions" and _DIGITS.fullmatch(second):
            return {"GET": (h_tx_get, _JSON), "DELETE": (h_tx_delete, _JSON)}
        if head == "budgets" and second == "status":
            return {"GET": (h_budgets_status, _JSON)}
        if head == "recurring" and second == "materialize":
            return {"POST": (h_materialize, _JSON)}
        if head == "reports" and second in _REPORTS:
            return {"GET": (h_report, _JSON)}
        return None
    if n == 3 and head == "accounts" and pieces[2] == "close":
        return {"POST": (h_account_close, _JSON)}
    return None


# -- the HTTP layer ----------------------------------------------------------


def _reason(status):
    try:
        return HTTPStatus(status).phrase
    except ValueError:
        return "Error"


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    timeout = REQUEST_TIMEOUT
    server_version = "tallybook"
    sys_version = ""

    def log_message(self, *args, **kwargs):
        pass

    def log_request(self, *args, **kwargs):
        pass

    def log_error(self, *args, **kwargs):
        pass

    def handle(self):
        try:
            self.close_connection = True
            self.handle_one_request()
        except Exception:
            pass

    def send_error(self, code, message=None, explain=None):
        self.close_connection = True
        self._send(400, JSON_TYPE, to_json({"error": "malformed request"}).encode("utf-8"))

    def handle_one_request(self):
        self.close_connection = True
        self._remaining = 0
        self.raw_requestline = self.rfile.readline(65537)
        if not self.raw_requestline:
            return
        if len(self.raw_requestline) > 65536:
            self.requestline = self.request_version = self.command = ""
            self.send_error(400)
            return
        if not self.parse_request():
            return
        self.close_connection = True
        words = self.requestline.split()
        if len(words) != 3:
            self.send_error(400)
            return
        self._dispatch(words[1])

    def _lenient_length(self):
        values = self.headers.get_all("Content-Length") or []
        if len(set(values)) == 1 and _DIGITS.fullmatch(values[0]) and values[0].isascii():
            return min(int(values[0].lstrip("0") or "0"), MAX_DRAIN)
        return 0

    def _drain(self):
        remaining, self._remaining = self._remaining, 0
        if remaining <= 0:
            return
        old = self.connection.gettimeout()
        try:
            self.connection.settimeout(min(old or 2.0, 2.0))
            while remaining > 0:
