                remaining -= len(chunk)
        except (OSError, ValueError):
            pass
        finally:
            try:
                self.connection.settimeout(old)
            except OSError:
                pass

    def _send(self, status, ctype, body, allow=None):
        self._drain()
        head = [
            "HTTP/1.1 %d %s" % (status, _reason(status)),
