    def _handle(self, target):
        pieces, raw_query = split_target(target)
        verbs = route(pieces) if pieces is not None else None
        if verbs is None:
            raise HttpError(404, "no such path")
        if self.command not in verbs:
            raise HttpError(405, "method not allowed: %s" % self.command, ", ".join(sorted(verbs)))
        handler, types = verbs[self.command]
        values = self.headers.get_all("Content-Length") or []
        length = 0
        if values:
            if len(set(values)) != 1 or _DIGITS.fullmatch(values[0]) is None or not values[0].isascii():
                raise HttpError(400, "invalid Content-Length")
            length = int(values[0].lstrip("0") or "0")
        body = b""
        content_type = ""
        if self.command in ("POST", "PUT"):
            if length > MAX_BODY:
                raise HttpError(413, "request body is larger than %d bytes" % MAX_BODY)
            body = self._read_body(length)
            content_type = (self.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
            if body and content_type not in types:
                raise HttpError(415, "unsupported content type: expected %s" % " or ".join(types))
